"""systemd --user units for `cg daemon`, with no hidden state.

The web app has no scheduler, so the daemon needs one. This module writes two
user units and owns nothing else:

    cg.service   one cycle (`daemon --once`) or a long-running daemon
    cg.timer     only for timer mode, fires the oneshot service

Design rules, learned from every brittle unit generator:

* the files are plain text, generated from one `ServiceSpec`;
* a unit not marked as generated by cg is never overwritten or removed;
* every systemctl call is one helper, so tests can patch a single seam;
* writes go through a temp file and `os.replace`, so a Ctrl+C never leaves a
  half-written unit behind.

`cg services` is the only caller; keeping the module importable means tests do
not need a user systemd session.
"""

from __future__ import annotations

import os
import re
import shlex
import shutil
import subprocess  # nosec B404
import sys
from dataclasses import dataclass, field
from pathlib import Path

DEFAULT_NAME = "cg"
DEFAULT_EVERY = "1h"
MODES = ("timer", "daemon")
MARKER = "# Generated by cg services"
UNIT_NAME_RE = re.compile(r"[A-Za-z0-9_.@-]+")
DURATION_RE = re.compile(r"^(\d+)([smhd]?)$")
SAFE_ARG_RE = re.compile(r"^[A-Za-z0-9_./:@+=,-]+$")
DURATION_UNITS = {"": 1, "s": 1, "m": 60, "h": 3600, "d": 86400}


# --------------------------------------------------------------------------- #
# paths and command line
# --------------------------------------------------------------------------- #


def default_unit_dir() -> Path:
    """Where `systemctl --user` looks for units, honouring XDG and CG_UNIT_DIR."""
    override = os.environ.get("CG_UNIT_DIR")
    if override:
        return Path(override).expanduser()
    base = Path(os.environ.get("XDG_CONFIG_HOME") or Path.home() / ".config")
    return base / "systemd" / "user"


def resolve_unit_dir(explicit: str | Path | None = None) -> Path:
    return Path(explicit).expanduser() if explicit else default_unit_dir()


def detect_cg_argv(explicit: str | None = None) -> list[str]:
    """The command the unit will run, preferring the stable `cg` in $PATH.

    Running from a worktree should not bake that worktree into a unit: if `cg`
    is installed, use the resolved symlink target. Without it, fall back to the
    script next to this module, then to the current interpreter.
    """
    if explicit:
        return [str(Path(explicit).expanduser())]
    found = shutil.which("cg")
    if found:
        return [str(Path(found).resolve())]
    script = Path(__file__).with_name("cg.py").resolve()
    if os.access(script, os.X_OK):
        return [str(script)]
    return [sys.executable, str(script)]


# --------------------------------------------------------------------------- #
# formatting helpers
# --------------------------------------------------------------------------- #


def parse_duration(text: str) -> int:
    """`30m`, `2h`, `1d` or a bare number of seconds -> seconds."""
    match = DURATION_RE.fullmatch(str(text).strip().lower())
    if not match:
        raise ValueError(f"duração inválida: {text!r} (use 30m, 1h, 2d)")
    seconds = int(match.group(1)) * DURATION_UNITS[match.group(2)]
    if seconds <= 0:
        raise ValueError("a duração precisa ser maior que zero")
    return seconds


def format_duration(seconds: int) -> str:
    for suffix, size in (("d", 86400), ("h", 3600), ("m", 60), ("s", 1)):
        if seconds % size == 0:
            return f"{seconds // size}{suffix}"
    return f"{seconds}s"


def jitter_delay(seconds: int) -> int:
    """A small randomized delay: never more than five minutes."""
    return min(300, max(1, seconds // 10))


def unit_quote(arg: str) -> str:
    """Quote one ExecStart argument for systemd's own parser.

    `%` introduces specifiers and `$` environment expansion; both must be
    doubled even inside quotes or a path with a dollar sign changes meaning.
    """
    escaped = (
        str(arg)
        .replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("%", "%%")
        .replace("$", "$$")
    )
    if SAFE_ARG_RE.fullmatch(str(arg)):
        return escaped
    return f'"{escaped}"'


def exec_start(argv: list[str]) -> str:
    return " ".join(unit_quote(arg) for arg in argv)


# --------------------------------------------------------------------------- #
# spec and unit text
# --------------------------------------------------------------------------- #


@dataclass(frozen=True)
class ServiceSpec:
    name: str = DEFAULT_NAME
    mode: str = "timer"
    apply: bool = False
    every: str = DEFAULT_EVERY
    wait_min: float | None = None
    wait_max: float | None = None
    unit_dir: Path = field(default_factory=default_unit_dir)
    cg_argv: list[str] = field(default_factory=detect_cg_argv)

    def __post_init__(self) -> None:
        if (
            not UNIT_NAME_RE.fullmatch(self.name)
            or self.name.startswith(".")
            or self.name in {".", ".."}
        ):
            raise ValueError(
                f"nome inválido: {self.name!r} (use letras, números, _ . @ -)"
            )
        if self.mode not in MODES:
            raise ValueError(f"modo inválido: {self.mode!r} (timer ou daemon)")
        try:
            parse_duration(self.every)
        except ValueError as exc:
            raise ValueError(str(exc)) from exc
        if self.wait_min is not None and self.wait_min < 0:
            raise ValueError("--wait-min não pode ser negativo")
        if self.wait_max is not None and self.wait_max < 0:
            raise ValueError("--wait-max não pode ser negativo")
        if (
            self.wait_min is not None
            and self.wait_max is not None
            and self.wait_max < self.wait_min
        ):
            raise ValueError("--wait-max precisa ser >= --wait-min")
        if not self.cg_argv:
            raise ValueError("não sei qual comando o systemd deve executar")

    @property
    def service_path(self) -> Path:
        return self.unit_dir / f"{self.name}.service"

    @property
    def timer_path(self) -> Path:
        return self.unit_dir / f"{self.name}.timer"

    @property
    def service_unit(self) -> str:
        return self.service_path.name

    @property
    def timer_unit(self) -> str:
        return self.timer_path.name

    @property
    def uses_timer(self) -> bool:
        return self.mode == "timer"

    @property
    def every_seconds(self) -> int:
        return parse_duration(self.every)

    def daemon_args(self) -> list[str]:
        args = ["daemon"]
        if self.uses_timer:
            args.append("--once")
        if self.apply:
            args.append("--yes")
        if not self.uses_timer:
            if self.wait_min is not None:
                args.extend(["--wait-min", f"{self.wait_min:g}"])
            if self.wait_max is not None:
                args.extend(["--wait-max", f"{self.wait_max:g}"])
        return args

    def exec_argv(self) -> list[str]:
        return [*self.cg_argv, *self.daemon_args()]


def render_service(spec: ServiceSpec) -> str:
    lines = [
        MARKER,
        "[Unit]",
        (
            "Description=cg daemon (one cycle, systemd timer)"
            if spec.uses_timer
            else "Description=cg daemon (long-running)"
        ),
        "",
        "[Service]",
        f"Type={'oneshot' if spec.uses_timer else 'simple'}",
        f"ExecStart={exec_start(spec.exec_argv())}",
    ]
    if spec.uses_timer:
        lines.append("TimeoutStartSec=2h")
    else:
        lines.extend(
            [
                "Restart=on-failure",
                "RestartSec=60",
                "SuccessExitStatus=143",
                "KillSignal=SIGTERM",
                "TimeoutStopSec=30",
            ]
        )
    lines.extend(["Nice=10", "IOSchedulingClass=idle"])
    if not spec.uses_timer:
        lines.extend(["", "[Install]", "WantedBy=default.target"])
    return "\n".join(lines) + "\n"


def render_timer(spec: ServiceSpec) -> str:
    seconds = spec.every_seconds
    return (
        "\n".join(
            [
                MARKER,
                "[Unit]",
                "Description=cg daemon timer",
                "",
                "[Timer]",
                "OnBootSec=2min",
                f"OnUnitActiveSec={format_duration(seconds)}",
                f"RandomizedDelaySec={format_duration(jitter_delay(seconds))}",
                "AccuracySec=1min",
                f"Unit={spec.service_unit}",
                "",
                "[Install]",
                "WantedBy=timers.target",
            ]
        )
        + "\n"
    )


def show(spec: ServiceSpec) -> int:
    _print_units(_rendered(spec))
    return 0


def _print_units(pairs: list[tuple[Path, str]]) -> None:
    for path, text in pairs:
        print(f"# {path}")
        print(text.rstrip())
        print()


def _rendered(spec: ServiceSpec) -> list[tuple[Path, str]]:
    pairs = [(spec.service_path, render_service(spec))]
    if spec.uses_timer:
        pairs.append((spec.timer_path, render_timer(spec)))
    return pairs


# --------------------------------------------------------------------------- #
# files
# --------------------------------------------------------------------------- #


def is_managed(path: Path) -> bool:
    try:
        with path.open(encoding="utf-8") as handle:
            return handle.read(256).startswith(MARKER)
    except OSError:
        return False


def write_unit(path: Path, text: str) -> bool:
    """Write atomically; return True when the file actually changed."""
    if path.exists():
        try:
            if path.read_text(encoding="utf-8") == text:
                return False
        except OSError:
            pass
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    try:
        tmp.write_text(text, encoding="utf-8")
        tmp.chmod(0o644)
        os.replace(tmp, path)
    finally:
        tmp.unlink(missing_ok=True)
    return True


def remove_unit(path: Path) -> bool:
    if not path.exists():
        return False
    path.unlink()
    return True


def discover_units(unit_dir: Path | None = None) -> list[Path]:
    root = unit_dir or default_unit_dir()
    if not root.is_dir():
        return []
    return sorted(
        path
        for path in root.iterdir()
        if path.is_file() and path.suffix in {".service", ".timer"} and is_managed(path)
    )


def _refuse_foreign(paths: list[Path], force: bool) -> None:
    for path in paths:
        if path.exists() and not is_managed(path) and not force:
            raise SystemExit(
                f"error: {path} não foi criado pelo cg.\n"
                "  Use --force para substituir ou escolha outro --name."
            )


# --------------------------------------------------------------------------- #
# systemctl seam
# --------------------------------------------------------------------------- #


def systemctl(
    *args: str,
    capture: bool = False,
    quiet: bool = False,
    dry_run: bool = False,
) -> tuple[int, str]:
    """Run `systemctl --user ...` and return (rc, captured stdout)."""
    argv = ["systemctl", "--user", *args]
    if dry_run:
        print(f"+ {shlex.join(argv)}")
        return 0, ""
    try:
        proc = subprocess.run(  # noqa: S603  # nosec B603
            argv,
            capture_output=capture,
            text=True,
            check=False,
        )
    except FileNotFoundError:
        if not quiet:
            print(
                "warning: systemctl não encontrado; unidades gravadas, "
                "mas não ativadas.",
                file=sys.stderr,
            )
        return 127, ""
    return proc.returncode, (proc.stdout or "").strip()


# --------------------------------------------------------------------------- #
# commands
# --------------------------------------------------------------------------- #


def register(
    spec: ServiceSpec,
    *,
    activate: bool = True,
    dry_run: bool = False,
    force: bool = False,
) -> int:
    pairs = _rendered(spec)
    stale_timer = None if spec.uses_timer else spec.timer_path
    check = [path for path, _text in pairs]
    if stale_timer is not None:
        check.append(stale_timer)
    _refuse_foreign(check, force)

    unit = spec.timer_unit if spec.uses_timer else spec.service_unit
    commands = [("daemon-reload",)]
    if activate:
        commands.append(("enable", "--now", unit))

    if dry_run:
        _print_units(pairs)
        if stale_timer is not None and stale_timer.exists():
            systemctl("stop", spec.service_unit, dry_run=True)
            systemctl("disable", "--now", spec.timer_unit, dry_run=True)
            print(f"# remover {stale_timer}")
        for command in commands:
            systemctl(*command, dry_run=True)
        return 0

    changed = sum(write_unit(path, text) for path, text in pairs)
    if stale_timer is not None and stale_timer.exists():
        systemctl("stop", spec.service_unit, capture=True, quiet=True)
        systemctl("disable", "--now", spec.timer_unit, capture=True, quiet=True)
        changed += remove_unit(stale_timer)

    reload_rc, _ = systemctl("daemon-reload", capture=True, quiet=True)
    if reload_rc != 0:
        print(
            "warning: systemctl --user falhou; as unidades estão em "
            f"{spec.unit_dir} e podem ser ativadas depois.",
            file=sys.stderr,
        )
        return reload_rc

    rc = 0
    if activate:
        rc, _ = systemctl("enable", "--now", unit)

    print(f"nome    : {spec.name}")
    print(f"modo    : {spec.mode}")
    print(f"serviço : {spec.service_path}")
    if spec.uses_timer:
        print(f"timer   : {spec.timer_path}")
    print(f"arquivos: {changed} atualizado(s)")
    if activate and rc == 0:
        print(f"estado  : {unit} ativado e iniciado")
    elif activate:
        print(
            f"estado  : unidade gravada; ative com "
            f"`systemctl --user enable --now {unit}`",
            file=sys.stderr,
        )
    else:
        print(f"estado  : unidade gravada, não ativada ({unit})")
    return rc


def unregister(
    spec: ServiceSpec,
    *,
    dry_run: bool = False,
    force: bool = False,
) -> int:
    existing = [path for path in (spec.service_path, spec.timer_path) if path.exists()]
    _refuse_foreign(existing, force)

    units = [spec.timer_unit, spec.service_unit]
    if dry_run:
        for unit in units:
            systemctl("disable", "--now", unit, dry_run=True)
        for path in existing:
            print(f"# remover {path}")
        systemctl("daemon-reload", dry_run=True)
        return 0

    for unit in units:
        systemctl("disable", "--now", unit, capture=True, quiet=True)
    removed = sum(remove_unit(path) for path in existing)
    reload_rc, _ = systemctl("daemon-reload", capture=True, quiet=True)

    print(f"nome    : {spec.name}")
    print(f"removido: {removed} arquivo(s)")
    if reload_rc not in (0, 127):
        print(
            "warning: systemctl --user não recarregou; "
            "rode `systemctl --user daemon-reload` na mão.",
            file=sys.stderr,
        )
    return 0


def status(spec: ServiceSpec) -> int:
    service_exists = spec.service_path.exists()
    timer_exists = spec.timer_path.exists()
    print(f"nome    : {spec.name}")
    print(f"serviço : {spec.service_path} ({'ok' if service_exists else 'ausente'})")
    print(f"timer   : {spec.timer_path} ({'ok' if timer_exists else 'ausente'})")
    if not service_exists and not timer_exists:
        print("\nnada registrado — rode `cg services register`.")
        return 1
    print(f"modo    : {'timer' if timer_exists else 'daemon'}")

    units = ([spec.timer_unit] if timer_exists else []) + (
        [spec.service_unit] if service_exists else []
    )
    for unit in units:
        _, active = systemctl("is-active", unit, capture=True, quiet=True)
        _, enabled = systemctl("is-enabled", unit, capture=True, quiet=True)
        print(
            f"{unit:18} ativo={active or 'desconhecido':12} "
            f"enabled={enabled or 'desconhecido'}"
        )

    if timer_exists:
        _, next_run = systemctl(
            "show",
            "-p",
            "NextElapseUSecRealtime",
            "--value",
            spec.timer_unit,
            capture=True,
            quiet=True,
        )
        if next_run and next_run != "n/a":
            print(f"próximo : {next_run}")
    return 0


def action(
    spec: ServiceSpec,
    verb: str,
    *,
    now: bool = False,
    dry_run: bool = False,
) -> int:
    service_exists = spec.service_path.exists()
    timer_exists = spec.timer_path.exists()
    if not service_exists and not timer_exists:
        raise SystemExit(
            f"error: {spec.name} não está registrado.\n"
            "  Rode `cg services register` primeiro."
        )

    target = spec.timer_unit if timer_exists else spec.service_unit
    if verb in {"start", "enable"}:
        command = [verb]
        if verb == "enable" and now:
            command.append("--now")
        return systemctl(*command, target, dry_run=dry_run)[0]

    if verb in {"stop", "disable"}:
        command = [verb]
        if verb == "disable" and now:
            command.append("--now")
        rc = 0
        if timer_exists:
            rc = rc or systemctl(*command, spec.timer_unit, dry_run=dry_run)[0]
        if service_exists and (verb == "stop" or now or not timer_exists):
            rc = rc or systemctl(*command, spec.service_unit, dry_run=dry_run)[0]
        return rc

    if verb == "restart":
        stopped = action(spec, "stop", dry_run=dry_run)
        return stopped or action(spec, "start", dry_run=dry_run)

    if verb == "run":
        if timer_exists:
            return systemctl("start", spec.service_unit, dry_run=dry_run)[0]
        return systemctl("restart", spec.service_unit, dry_run=dry_run)[0]

    raise SystemExit(f"error: ação desconhecida: {verb}")


def logs(
    spec: ServiceSpec,
    *,
    lines: int = 60,
    follow: bool = False,
    dry_run: bool = False,
) -> int:
    argv = [
        "journalctl",
        "--user",
        "-u",
        spec.service_unit,
        "-n",
        str(lines),
        "--no-pager",
    ]
    if follow:
        argv.append("-f")
    if dry_run:
        print(f"+ {shlex.join(argv)}")
        return 0
    try:
        proc = subprocess.run(argv, check=False)  # noqa: S603  # nosec B603
    except FileNotFoundError:
        print("warning: journalctl não encontrado.", file=sys.stderr)
        return 127
    return proc.returncode


def list_registered(unit_dir: Path | None = None) -> int:
    path = unit_dir or default_unit_dir()
    units = discover_units(path)
    if not units:
        print(f"nenhuma unidade cg em {path}")
        return 0
    for unit in units:
        print(f"{unit.stem:20} {unit.suffix[1:]:8} {unit}")
    return 0
